#include <stdlib.h>
#include "dice_header_api.h"
unsigned int dice_header_calls = 0u;
static int one_die(int sides) {
    dice_header_calls++;
    return rand() % sides + 1;
}
int dice_header_many(int dice, int sides) {
    if (dice < 1 || dice > 8 || sides < 2 || sides > 20) return -1;
    int sum = 0;
    for (int i = 0; i < dice; i++) sum += one_die(sides);
    return sum;
}

