#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int capacity = 0;
    if (scanf("%d", &capacity) != 1 || capacity < 1 || capacity > 8) return 1;
    double *data = malloc((size_t)capacity * sizeof *data);
    if (data == NULL) return 1;
    int used = 0;
    while (used < capacity && scanf("%lf", &data[used]) == 1) used++;
    printf("stored=%d\n", used);
    for (int i = 0; i < used; i++) printf("%.1f\n", data[i]);
    free(data);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int stored = 12;
const char *literal = "STATIC TEXT";
int main(void) {
    int temporary = 24;
    char automatic[] = "LOCAL TEXT";
    int *number = malloc(sizeof *number);
    char *dynamic = malloc(strlen("DYNAMIC TEXT") + 1);
    if (number == NULL || dynamic == NULL) {
        free(number);
        free(dynamic);
        return 1;
    }
    *number = 36;
    strcpy(dynamic, "DYNAMIC TEXT");
    printf("static=%d at=%p\n", stored, (void *)&stored);
    printf("automatic=%d at=%p\n", temporary, (void *)&temporary);
    printf("allocated=%d at=%p\n", *number, (void *)number);
    printf("literal=%s at=%p\n", literal, (void *)literal);
    printf("array=%s at=%p\n", automatic, (void *)automatic);
    printf("dynamic=%s at=%p\n", dynamic, (void *)dynamic);
    free(number);
    free(dynamic);
    return 0;
}

