#include <stdio.h>
int advance(void);
int main(void) {
    int count = 0;
    if (scanf("%d", &count) != 1 || count < 0 || count > 4) return 1;
    if (count == 0) {
        printf("0\n");
        return 0;
    }
    int last = 0;
    for (int i = 0; i < count; i++) last = advance();
    printf("%d\n", last);
    return 0;
}
int advance(void) {
    static int stored = 0;
    stored += 3;
    return stored;
}

