#include <stdio.h>
void visit(void)
{
    int local = 0;
    static int saved = 0; // 对象跨调用保留；这个初始化不会每次重做。
    ++local;
    ++saved;
    printf("local=%d saved=%d\n", local, saved);
}
int main(void)
{
    visit();
    visit();
    visit();
    return 0;
}

#include <stdio.h>
int main(void)
{
    int value = 4;
    printf("outer=%d\n", value);
    {
        int value = 9; // 从此声明起，内层名字遮蔽外层同名声明。
        printf("inner=%d\n", value);
    }
    for (int value = 0; value < 2; ++value)
        printf("loop=%d\n", value);
    printf("outer=%d\n", value);
    return 0;
}

#include <stdio.h>
#include "state.h"
static int private_count = 100; // 这个名字的内部链接局限于当前翻译单元。
int main(void)
{
    bump();
    bump();
    printf("shared=%d module=%d main=%d\n",
           shared, module_count(), private_count);
    return 0;
}

#ifndef STATE_H
#define STATE_H
extern int shared; // 声明共享对象，定义只放在一个.c文件中。
void bump(void);
int module_count(void);
#endif

#include "state.h"
int shared = 0;
static int private_count = 10;
static void increment_private(void)
{
    ++private_count;
}
void bump(void)
{
    ++shared;
    increment_private();
}
int module_count(void)
{
    return private_count;
}

