#ifndef DICE_H
#define DICE_H
extern int roll_count;
int roll_pair(int sides);
#endif

#include <stdlib.h>
#include "dice.h"
int roll_count = 0;
static int roll_one(int sides)
{
    ++roll_count; // 计的是单颗骰子的生成次数。
    return rand() % sides + 1;
}
int roll_pair(int sides)
{
    if (sides < 1 || sides > 6) return 0;
    int first = roll_one(sides);
    int second = roll_one(sides);
    return first + second;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
int main(void)
{
    int requested;
    if (scanf("%d", &requested) != 1 || requested < 1 || requested > 4) {
        puts("invalid");
        return 0;
    }
    size_t count = (size_t)requested;
    int *items;
    if (count > SIZE_MAX / sizeof *items) { // 先检查乘积，避免字节数回绕。
        puts("too large");
        return 0;
    }
    items = malloc(count * sizeof *items);
    if (items == NULL) {
        puts("no memory");
        return 0;
    }
    int sum = 0;
    for (size_t i = 0; i < count; ++i) {
        items[i] = (int)i + 1; // malloc没有替这些int建立初值。
        sum += items[i];
    }
    printf("sum=%d\n", sum);
    free(items);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
void temporary_sum(const int source[3])
{
    int *copy = malloc(3 * sizeof *copy);
    if (copy == NULL) {
        puts("no memory");
        return;
    }
    int sum = 0;
    for (int i = 0; i < 3; ++i) {
        copy[i] = source[i];
        sum += copy[i];
    }
    printf("sum=%d\n", sum);
    free(copy); // 本函数拥有这个临时分配，正常返回前归还它。
}
int main(void)
{
    int source[3] = {1, 2, 3};
    temporary_sum(source);
    temporary_sum(source);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
int main(void)
{
    int *items;
    if (3 > SIZE_MAX / sizeof *items) {
        puts("too large");
        return 0;
    }
    items = calloc(3, sizeof *items);
    if (items == NULL) {
        puts("no memory");
        return 0;
    }
    items[1] = 8;
    printf("%d %d %d\n", items[0], items[1], items[2]);
    free(items);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    int *saved = NULL;
    {
        int count = 3;
        int local[count];
        saved = malloc(sizeof local);
        if (saved == NULL) {
            puts("no memory");
            return 0;
        }
        for (int i = 0; i < count; ++i) {
            local[i] = i + 4;
            saved[i] = local[i];
        }
    } // local的寿命结束；saved所指分配的寿命尚未结束。
    printf("%d\n", saved[2]);
    free(saved);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int *make_value(void)
{
    int *result = malloc(sizeof *result);
    if (result != NULL) *result = 9;
    return result; // 转交分配的所有权；不是返回局部int对象的地址。
}
int main(void)
{
    int *value = make_value();
    if (value == NULL) {
        puts("no memory");
        return 0;
    }
    printf("%d\n", *value);
    free(value);
    return 0;
}

#include <stdio.h>
int main(void)
{
    int value = 6;
    const int *read = &value; // 不能经read改值，原对象本身仍可写。
    int *const fixed = &value; // 固定的是这个指针对象，所指int仍可写。
    *fixed = 8;
    printf("value=%d read=%d fixed=%d\n", value, *read, *fixed);
    return 0;
}

#include <stdio.h>
int main(void)
{
    volatile int sample = 5;
    int first = sample;
    sample = 7;
    int second = sample;
    printf("first=%d second=%d\n", first, second);
    return 0;
}

#include <stdio.h>
void add_three(int *restrict target, const int *restrict source)
{
    for (int i = 0; i < 3; ++i)
        target[i] += source[i];
}
int main(void)
{
    int target[3] = {10, 20, 30};
    int source[3] = {1, 2, 3};
    add_three(target, source); // 本次调用的写入区域与source区域不重叠。
    printf("%d %d %d source=%d\n",
           target[0], target[1], target[2], source[0]);
    return 0;
}

#include <stdio.h>
#include <stdatomic.h>
int main(void)
{
    _Atomic int count;
    atomic_init(&count, 1);
    int old = atomic_fetch_add(&count, 1); // 取旧值并增加，作为一次原子读改写。
    int now = atomic_load(&count);
    printf("old=%d now=%d\n", old, now);
    return 0;
}

#include <stdio.h>
int sum_three(const int values[static 3]) // 调用者至少提供可访问的三个元素。
{
    return values[0] + values[1] + values[2];
}
void set_first(int values[const 3]) // 调整为int *const，不是const int *。
{
    values[0] = 9;
}
int main(void)
{
    int values[3] = {1, 2, 3};
    printf("%d\n", sum_three(values));
    set_first(values);
    printf("%d\n", sum_three(values));
    return 0;
}
